// generated by agent-handoffs from .claude/crew.yaml. Edit crew.yaml and re-render; hand edits are overwritten.
export const meta = {
  name: 'handoff',
  description: "Run a task through the Blog crew: developer → qa → reviewer",
  whenToUse: 'A task that should pass through every role in order. args: {task: "what to do" (required), run: "YYYY-MM-DD-short-slug" (required; workflow scripts cannot read the clock), start?: "<role>" to skip earlier stages}. Notes land in .handoffs/<run>/.',
  phases: [{"title": "developer", "detail": "Implements a change in the codebase, following the project's conventions, and leaves it passing the project's checks. Use for writing or changing code."}, {"title": "qa", "detail": "Verifies a change actually works, beyond the developer's own tests, by exercising it, probing edge cases and writing missing tests. Use after implementation and before review."}, {"title": "reviewer", "detail": "Reviews the finished change for correctness, design, conventions and risk before it is accepted. Read-only on product code. Use as the last gate."}, {"title": "brain capture", "detail": "queue the run's notes for the second-brain curator"}],
}

const ROOT = "C:/Users/Robert/projects/Blog"
const PIPELINE = ["developer", "qa", "reviewer"]
const MAX_SEND_BACKS = 2

const argv = typeof args === 'string' ? JSON.parse(args) : (args || {})
if (!argv.task) {
  throw new Error('args.task required: what the crew should do')
}
if (!argv.run || !/^\d{4}-\d{2}-\d{2}-[a-z0-9-]+$/.test(argv.run)) {
  throw new Error('args.run required as "YYYY-MM-DD-short-slug" (workflow scripts cannot read the clock)')
}
const RUN_DIR = `${ROOT}/.handoffs/${argv.run}`
let i = argv.start ? PIPELINE.indexOf(argv.start) : 0
if (i < 0) {
  throw new Error(`args.start must be one of ${PIPELINE.join(', ')}`)
}

const HANDOFF_SCHEMA = {
  type: 'object',
  required: ['status', 'summary', 'note', 'send_back_to', 'open_questions'],
  additionalProperties: false,
  properties: {
    status: { type: 'string', enum: ['done', 'send_back', 'blocked'] },
    summary: { type: 'string', description: 'two or three sentences: what this stage did and concluded' },
    note: { type: 'string', description: 'absolute path of the handoff note written' },
    send_back_to: { type: ['string', 'null'], enum: [...PIPELINE, null], description: 'earlier stage that must redo work; null unless status is send_back' },
    open_questions: { type: 'array', items: { type: 'string' } },
  },
}

const stagePrompt = (role, step, history) => `
You are the \`${role}\` stage of a handoff pipeline in ${ROOT}.
Your role definition is ${ROOT}/.claude/agents/${role}.md. Read it now (skip its YAML frontmatter) and follow it.

Task: ${argv.task}

Run directory: ${RUN_DIR} (create it if it doesn't exist). Read every note already in it before you start.
Write your note to: ${RUN_DIR}/${String(step).padStart(2, '0')}-${role}.md
Stages so far:
${history.length ? history.map((h) => `- ${h.step} ${h.role} [${h.status}]: ${h.summary}`).join('\n') : '- none, you are first'}

Return only the handoff object. The note stays on disk, so don't include its text in your reply.
`.trim()

const history = []
let sendBacks = 0
let step = 0
let result = null
while (i < PIPELINE.length && !result) {
  const role = PIPELINE[i]
  step += 1
  phase(role)
  const res = await agent(stagePrompt(role, step, history), {
    label: `${String(step).padStart(2, '0')}:${role}`,
    phase: role,
    schema: HANDOFF_SCHEMA,
  })
  if (!res) {
    result = { status: 'failed', run: argv.run, failed_stage: role, history }
    break
  }
  history.push({ step, role, ...res })
  if (res.status === 'blocked') {
    result = { status: 'blocked', run: argv.run, blocked_at: role, history }
    break
  }
  if (res.status === 'send_back') {
    const target = PIPELINE.indexOf(res.send_back_to)
    if (target < 0 || target >= i) {
      log(`${role} asked to send back to ${res.send_back_to}, which is not an earlier stage; stopping`)
      result = { status: 'blocked', run: argv.run, blocked_at: role, history }
      break
    }
    if (sendBacks >= MAX_SEND_BACKS) {
      result = { status: 'send_backs_exhausted', run: argv.run, last_stage: role, history }
      break
    }
    sendBacks += 1
    log(`send-back ${sendBacks}/${MAX_SEND_BACKS}: ${role} → ${res.send_back_to}`)
    i = target
    continue
  }
  i += 1
}
result = result || { status: 'done', run: argv.run, notes: RUN_DIR, history }

// Queue the run's notes for the second-brain curator. Capture only: the curator runs asynchronously.
if (history.length) {
  phase('brain capture')
  await agent(`
Queue this crew run for the second brain. Run exactly this one command and nothing else:

docker compose -f C:/Users/Robert/projects/second-brain/docker-compose.yml run --rm app brain inbox add --source crew --project "Blog" --text ${JSON.stringify(`Crew run ${argv.run} (${result.status}) for task: ${argv.task}. Handoff notes, each with a Brain section of durable learnings: ${RUN_DIR}/. Read them and curate what is durable.`)}

If Docker isn't running, start Docker Desktop and retry once. If it still fails, say so; don't retry further.
`.trim(), { label: 'brain-capture', phase: 'brain capture' })
}

return result
